+/// The bench whose C states `travel` but no rate at all - neither feed
+/// nor rapid (#906).
+fn unrated(travel: (f64, f64)) -> Machine {
+    let mut m = mill_turn(Some(travel));
+    for a in m.axes.iter_mut().filter(|a| a.rotary) {
+        (a.feed, a.rapid) = (None, None);
+    }
+    m
+}
